; pic8 -- P2 integer spine (isel-pic18)
    list p=p18f4550
    radix hex

    org 0x0000
    goto __start

sum:
    MOVFF 0x030, 0x034
    MOVFF 0x032, 0x035
    MOVFF 0x033, 0x036
    MOVFF 0x035, 0x037
    MOVF 0x037,W,A
    ADDWF 0x034,W,A
    MOVWF 0x038,A
    MOVF 0x038,W,A
    MOVWF 0x000,A
    RETURN
pick:
    MOVFF 0x030, 0x035
    MOVFF 0x035, 0x036
    MOVLW 0x00
    MOVWF 0x037,A
    LFSR 0, 0x031
    MOVF 0x036,W,A
    ADDWF 0x0E9,F,A
    MOVLW 0x00
    ADDWFC 0x0EA,F,A
    MOVFF 0xFEF, 0x038
    MOVF 0x038,W,A
    MOVWF 0x000,A
    RETURN
mk:
    MOVFF 0x030, 0xFE9
