    ADDWF 0x0E9,F,A
    MOVLW 0x00
    ADDWFC 0x0EA,F,A
    MOVF 0x034,W,A
    MOVWF 0xFEF,A
    RETURN
main:
    MOVLW 0x16
    MOVWF 0x030,A
    MOVLW 0x00
    MOVWF 0x031,A
    MOVLW 0x03
    MOVWF 0x032,A
    MOVLW 0x34
    MOVWF 0x033,A
    MOVLW 0x12
    MOVWF 0x034,A
    CALL mk
    MOVFF 0x016, 0x004
    MOVFF 0x017, 0x005
    MOVFF 0x018, 0x006
    MOVFF 0x019, 0x007
    MOVFF 0x004, 0x030
    MOVFF 0x005, 0x031
    MOVFF 0x006, 0x032
    MOVFF 0x007, 0x033
    CALL sum
    MOVFF 0x000, 0x01A
    MOVFF 0x01A, 0x008
    MOVLW 0x02
    MOVWF 0x00A,A
    MOVLW 0x5A
    MOVWF 0x00D,A
    MOVFF 0x00A, 0x01B
    MOVFF 0x01B, 0x01C
    MOVLW 0x00
    MOVWF 0x01D,A
    LFSR 0, 0x00B
    MOVF 0x01C,W,A
    ADDWF 0x0E9,F,A
    MOVLW 0x00
    ADDWFC 0x0EA,F,A
    MOVLW 0x11
    MOVWF 0xFEF,A
    MOVFF 0x008, 0x01E
    MOVFF 0x00A, 0x030
    MOVFF 0x00B, 0x031
    MOVFF 0x00C, 0x032
    MOVFF 0x00D, 0x033
    MOVFF 0x00E, 0x034
    CALL pick
    MOVFF 0x000, 0x01F
    MOVF 0x01E,W,A
    ADDWF 0x01F,W,A
    MOVWF 0x020,A
    MOVFF 0x020, 0x008
    MOVLW 0x01
    MOVWF 0x010,A
    MOVLW 0x02
    MOVWF 0x012,A
    MOVLW 0x00
    MOVWF 0x013,A
    MOVLW 0x03
    MOVWF 0x014,A
    MOVFF 0x008, 0x021
    MOVFF 0x021, 0x022
    MOVLW 0x00
    MOVWF 0x023,A
    MOVFF 0x010, 0x024
    MOVFF 0x024, 0x025
    MOVLW 0x00
    MOVWF 0x026,A
    MOVF 0x022,W,A
    ADDWF 0x025,W,A
    MOVWF 0x027,A
    MOVF 0x023,W,A
    ADDWFC 0x026,W,A
    MOVWF 0x028,A
    MOVFF 0x012, 0x029
    MOVFF 0x013, 0x02A
    MOVF 0x029,W,A
    ADDWF 0x027,W,A
    MOVWF 0x02B,A
    MOVF 0x02A,W,A
    ADDWFC 0x028,W,A
    MOVWF 0x02C,A
    MOVFF 0x014, 0x02D
    MOVFF 0x02B, 0x02E
    MOVF 0x02E,W,A
    ADDWF 0x02D,W,A
    MOVWF 0x02F,A
    MOVFF 0x02F, 0x008
